COLS = [('study', 'study', 'ONEIL or ALMANAC (DrugCombDB study_source)'), ('unit_id', 'unit_id', "O'Neil: drugA|drugB|cell_line|batch{0,1}; ALMANAC: DrugCombDB experiment_id"), ('drug_row', 'drugA', 'drug on the rows (dose index i), DrugCombDB name'), ('drug_col', 'drugB', 'drug on the columns (dose index j), DrugCombDB name'), ('cell_line', 'cell_line', 'cell line (DrugCombDB)'), ('batch', 'batch', "O'Neil batch (0; 0 or 1 for the 315 groups measured twice); empty for ALMANAC"), ('family', 'family', "BH testing family: study, cell line and (O'Neil) batch"), ('design', None, 'analysis design (see null_tested)'), ('null_tested', None, 'null hypothesis of the SIR statistic for this study'), ('experiment_ids', 'experiment_ids', 'contributing DrugCombDB block ids'), ('n_replicates', None, "replicate plates analyzed (4 O'Neil blocks; 1 ALMANAC plate)"), ('doses_row_uM', 'doses_a_analyzed', "nonzero row-drug doses analyzed, uM, ';'-separated"), ('doses_col_uM', 'doses_b_analyzed', 'nonzero column-drug doses analyzed, uM'), ('control_raw', 'control_raw', 'raw control well (Response / 100); every plate was divided by it'), ('edge_row_top', 'edgeA_top', "row-drug single-agent viability at its top dose (O'Neil: reported curve)"), ('edge_col_top', 'edgeB_top', 'column-drug single-agent viability at its top dose'), ('activity', 'activity', 'mean of 1 - viability over the combination wells'), ('activity_all_wells', 'activity_all_wells', 'mean of 1 - viability over all non-control wells'), ('mean_bliss_prediction', 'mean_bliss_pred', 'mean over combination cells of a_hat_i b_hat_j (isotonic single agents)'), ('mean_excess', 'mean_excess', 'raw mean viability Bliss excess, mean of Y_i0 Y_0j - Y_ij (positive = more killing than Bliss)'), ('mean_excess_se', 'mean_excess_se', 'standard error of mean_excess from the companion test'), ('companion_test', 'companion_test', "companion mean test (O'Neil: block-level t, df 3; ALMANAC: V2Sp)"), ('companion_t', 'companion_t', 'companion t statistic'), ('companion_df', 'companion_df', 'companion degrees of freedom'), ('p_companion', 'p_companion', 'one-sided p-value of the companion test (null: no synergy on average)'), ('q_companion', 'q_companion', 'BH q-value of p_companion within family'), ('p_companion_relnull', 'p_companion_relnull', 'companion p-value against the within-family empirical null (relative null: stronger than typical for the family)'), ('q_companion_relnull', 'q_companion_relnull', 'BH q-value of p_companion_relnull within family'), ('fixed_edge_t', 'fe_t', "O'Neil only: fixed-edge viability t with the cross-fitted block-shift variance / 4 (df 15)"), ('p_fixed_edge', 'p_fixed_edge', "O'Neil only: one-sided p-value of fixed_edge_t"), ('fixed_edge_block_var', 'fe_plate_var', "O'Neil only: block-shift variance component used by fixed_edge_t"), ('p_mean_boot', 'p_mean_boot', 'bootstrap-calibrated raw mean excess on the SIR reference plates'), ('t_std', 't_std', 'SIR statistic = sum ((a_hat_i b_hat_j - P_M(Y)_ij) / s(a_hat_i b_hat_j))_+^2'), ('p_tstd', 'p_tstd', 'p-value of the SIR statistic (stage 2, B = 9,999, when a stage-1 p was <= 0.05; else stage 1, B = 399)'), ('p_tstd_stage1', 'p_tstd_stage1', 'stage-1 p-value of the SIR statistic (B = 399)'), ('mc_stage', 'stage', 'Monte Carlo stage reported (1 or 2)'), ('mc_B', 'B_used', 'reference plates behind p_tstd and p_scan'), ('q_tstd', 'q_tstd', 'BH q-value of p_tstd within family'), ('p_tstd_floored', 'p_tstd_floored', 'ALMANAC only: p_tstd floored at 1 / (2 x bank pool + 1), the resolution of the plate-difference bank'), ('q_tstd_floored', 'q_tstd_floored', 'ALMANAC only: BH q-value of p_tstd_floored within family'), ('bank_pool_sets', 'bank_pool_sets', 'eligible noise-bank sets (potency stratum, other cell-line half)'), ('p_scan', 'p_scan', 'region scan global p-value (single-step max-T over high-dose rectangles and 2x2 blocks); exploratory on real data'), ('p_scan_stage1', 'p_scan_stage1', 'stage-1 scan p-value'), ('top_region', 'top_region', "region with the smallest adjusted p ('i,j' cells, original dose indices)"), ('top_region_type', 'top_region_type', 'rectangle (high-dose) and/or 2x2 block'), ('top_region_z', 'top_region_z', 'standardized raw-well region sum of top_region'), ('top_region_p_adj', 'top_region_p_adj', 'familywise-adjusted p-value of top_region (within matrix)'), ('fragility_cell', 'loco_cell', 'ALMANAC plates with p_tstd <= 0.05: most influential combination cell'), ('fragility_cell_p', 'loco_p', 'p_tstd with that cell set to missing'), ('fragility_cell_share', 'loco_influence_share', 'share of the SIR statistic contributed by that cell'), ('fragility_sa_dose', 'sa_dose', 'most influential single-agent dose (drug, index)'), ('fragility_sa_p', 'sa_p', 'p_tstd with that dose row/column dropped'), ('fragility_sa_share', 'sa_influence_share', 'share of the SIR statistic removed by dropping it'), ('n_dropped_doses', 'n_dropped_doses', 'rule R: single-agent doses dropped because missing'), ('n_missing_cells', 'n_missing_cells', 'missing combination wells'), ('n_screened', 'n_screened', "O'Neil: replicate values removed by the 5-model-SD replicate screen"), ('screened', 'screened', 'screened values: (i,j) replicate and distance in model SDs'), ('reference_flags_per_plate', 'reference_flags_per_plate', 'mean screened values per reference plate (same screen in the reference)'), ('companion_degenerate', 'companion_degenerate', 'companion SE zero or not finite (p is NaN)'), ('log_notes', 'log_notes', 'data-handling and reference notes from sirsyn (noise-bank stratum, pool, cross-fitting)'), ('seed_entropy', 'seed_entropy', 'seed entropy of the sirsyn fit (reproducible)')]
# Public column descriptions (same text as the deposited schema.json)
DESCRIPTIONS = {'study': 'ONEIL or ALMANAC (DrugCombDB source study)', 'unit_id': "analysis unit. O'Neil: drugA|drugB|cell_line|batch{0,1} (four replicate blocks); ALMANAC: DrugCombDB experiment id (one plate)", 'drug_row': 'drug on the rows (dose index i), DrugCombDB name', 'drug_col': 'drug on the columns (dose index j), DrugCombDB name', 'cell_line': 'cell line (DrugCombDB)', 'batch': "O'Neil batch (0, or 0 and 1 for the 315 drug pair and cell line groups measured twice); empty for ALMANAC", 'family': "Benjamini-Hochberg testing family: study, cell line and (O'Neil) batch", 'design': 'analysis design. P: replicate blocks with the reported single-agent curves held fixed; S: single plate with single agents measured on the plate', 'null_tested': 'null hypothesis of the SIR statistic for this unit', 'experiment_ids': 'contributing DrugCombDB block ids', 'n_replicates': "replicate plates analyzed (4 O'Neil blocks; 1 ALMANAC plate)", 'doses_row_uM': "row-drug doses analyzed, including zero, uM, ';'-separated", 'doses_col_uM': "column-drug doses analyzed, including zero, uM, ';'-separated", 'control_raw': 'raw control well (Response / 100); every plate is divided by its control', 'edge_row_top': "row-drug single-agent viability at its top dose (O'Neil: reported curve)", 'edge_col_top': "column-drug single-agent viability at its top dose (O'Neil: reported curve)", 'activity': "activity: mean of 1 - viability over the combination wells (O'Neil: of the replicate means at each well, after the replicate screen)", 'activity_all_wells': 'mean of 1 - viability over all non-control wells', 'mean_bliss_prediction': 'mean over combination cells of the Bliss prediction a_hat_i b_hat_j (isotonic single-agent fits)', 'mean_excess': "mean viability Bliss excess on raw wells, Y_i0 Y_0j - Y_ij averaged over combination cells (positive: more killing than Bliss). ALMANAC: the cell average of the plate. O'Neil: the block-level estimate, the average over the four plates of each plate's cell average (the estimate of the companion block-level t test); it equals the cell average of the replicate means when no replicate value was screened (n_screened = 0)", 'mean_excess_se': "standard error of mean_excess from the companion test (O'Neil: block-level, conditional on the reported single-agent curves)", 'companion_test': "companion mean test (O'Neil: block-level t, 3 df; ALMANAC: V2Sp)", 'companion_t': 'companion t statistic', 'companion_df': 'companion degrees of freedom', 'p_companion': 'one-sided p-value of the companion test (null: no synergy on average)', 'q_companion': 'BH q-value of p_companion within family', 'p_companion_relnull': 'companion p-value against the within-family empirical null (relative null: stronger than typical for the family)', 'q_companion_relnull': 'BH q-value of p_companion_relnull within family', 'fixed_edge_t': "O'Neil only: fixed-edge viability t with the cross-fitted block-shift variance divided by 4 (15 df)", 'p_fixed_edge': "O'Neil only: one-sided p-value of fixed_edge_t", 'fixed_edge_block_var': "O'Neil only: block-shift variance component used by fixed_edge_t", 'p_mean_boot': 'p-value of the raw mean excess calibrated on the reference plates of the SIR statistic', 't_std': 'the SIR statistic T_SIR = sum over combination cells of ((a_hat_i b_hat_j - mu_hat_ij) / s(a_hat_i b_hat_j))_+^2, mu_hat the 2D isotonic fit', 'p_tstd': 'p-value of the SIR statistic (plug-in parametric bootstrap at exact Bliss; B = 9,999 when a stage-1 p-value was <= 0.05, otherwise B = 399)', 'p_tstd_stage1': 'stage-1 p-value of the SIR statistic (B = 399)', 'mc_stage': 'Monte Carlo stage reported (1 or 2)', 'mc_B': 'reference plates behind p_tstd and p_scan', 'q_tstd': 'BH q-value of p_tstd within family', 'p_tstd_floored': 'ALMANAC only: p_tstd floored at 1 / (2 x bank pool + 1), the resolution of the plate-difference noise bank', 'q_tstd_floored': 'ALMANAC only: BH q-value of p_tstd_floored within family', 'bank_pool_sets': 'eligible noise-bank sets (potency stratum, other half of the cell lines)', 'p_scan': 'region scan global p-value (single-step max-T over high-dose rectangles and 2x2 blocks)', 'p_scan_stage1': 'stage-1 region scan p-value', 'top_region': "region with the smallest adjusted p-value ('i,j' cells, original dose indices)", 'top_region_type': 'rectangle (high-dose) and/or 2x2 block', 'top_region_z': 'standardized raw-well region sum of top_region', 'top_region_p_adj': 'familywise-adjusted p-value of top_region (within the matrix)', 'fragility_cell': 'ALMANAC plates with p_tstd <= 0.05: most influential combination cell', 'fragility_cell_p': 'p_tstd with that cell set to missing', 'fragility_cell_share': 'share of the SIR statistic contributed by that cell', 'fragility_sa_dose': 'most influential single-agent dose (drug, index)', 'fragility_sa_p': 'p_tstd with that dose row or column dropped', 'fragility_sa_share': 'share of the SIR statistic removed by dropping it', 'n_dropped_doses': 'single-agent doses dropped because the single-agent well was missing (the dose row or column is removed)', 'n_missing_cells': 'missing combination wells', 'n_screened': "O'Neil: replicate values removed by the replicate screen (more than 5 model SDs from the median of the other replicates)", 'screened': 'screened values: (i,j), replicate and distance in model SDs', 'reference_flags_per_plate': 'mean screened values per reference plate (the same screen is applied to the reference)', 'companion_degenerate': 'companion SE zero or not finite (p-value is NaN)', 'log_notes': 'data-handling and reference notes (noise-bank stratum, pool size, cross-fitting group)', 'seed_entropy': 'seed entropy of the fit (reruns reproduce the unit exactly)'}


def sha(p):
    h = hashlib.sha256()
    with open(p, 'rb') as f:
        for b in iter(lambda : f.read(1 << 20), b''):
            h.update(b)
    return h.hexdigest()

def build(d, study):
    out = pd.DataFrame(index=d.index)
    for (name, src, _) in COLS:
        if src is not None:
            out[name] = d[src] if src in d else np.nan
    out['study'] = 'ONEIL' if study == 'oneil' else 'ALMANAC'
    if study == 'oneil':
        out['design'] = "P: 4 replicate blocks, external single-agent curves fixed, replicate screen, O'Neil noise bank"
        out['null_tested'] = 'no synergy in any combination cell relative to the reported single-agent curves (curves fixed)'
        out['n_replicates'] = 4
    else:
        out['design'] = 'S: single plate, single agents on the plate, ALMANAC plate-difference bank'
        out['null_tested'] = 'no synergy in any combination cell (Bliss on viability, single agents on the plate)'
        out['n_replicates'] = 1
        out['batch'] = np.nan
        out['experiment_ids'] = d['experiment_id']
    return out[[c[0] for c in COLS]]

def main():
    os.makedirs(OUT, exist_ok=True)
    dO = pd.read_parquet(os.path.join(C.RES, 'screen_oneil_q.parquet'))
    dA = pd.read_parquet(os.path.join(C.RES, 'screen_almanac_q.parquet'))
    R = pd.concat([build(dO, 'oneil'), build(dA, 'almanac')], ignore_index=True)
    R['batch'] = R.batch.astype('Int64')
    pq = os.path.join(OUT, 'sir_drugcombdb_unit_results.parquet')
    csv = os.path.join(OUT, 'sir_drugcombdb_unit_results.csv')
    R.to_parquet(pq, index=False)
    R.to_csv(csv, index=False, float_format='%.8g')
    schema = dict(title="SIR per-unit synergy test results for DrugCombDB (O'Neil and NCI-ALMANAC)", rows=int(len(R)), rows_by_study=R.study.value_counts().to_dict(), package=f'sirsyn {C.S.__version__}', specification='SIR 0.2.0; reproduction configuration', null_tested=C.NULL_NOTE, labels='no binary synergy labels; use p and q values within the declared family', columns=[dict(name=n, dtype=str(R[n].dtype), description=DESCRIPTIONS[n]) for (n, _, dsc) in COLS])
    sp = os.path.join(OUT, 'schema.json')
    with open(sp, 'w') as f:
        json.dump(schema, f, indent=1)
    with open(os.path.join(OUT, 'SHA256SUMS.txt'), 'w') as f:
        for p in (pq, csv, sp):
            f.write(f'{sha(p)}  {os.path.basename(p)}\n')
    print(open(os.path.join(OUT, 'SHA256SUMS.txt')).read(), len(R))
if __name__ == '__main__':
    main()
